package com.runnersz.desktop.service;
import com.runnersz.desktop.model.ServerConfig;import java.net.URI;import java.net.http.*;import java.nio.file.*;import java.util.*;import java.io.IOException;
public final class ApiClient{private final ServerConfig config;private final HttpClient http=HttpClient.newHttpClient();public ApiClient(ServerConfig c){config=c;}
 public byte[] decrypt(Path file,String password)throws Exception{return multipart("/api/v1/files/decrypt",file,password);}
 public byte[] encrypt(Path file,String password)throws Exception{return multipart("/api/v1/files/encrypt",file,password);}
 private byte[] multipart(String path,Path file,String password)throws Exception{String b="----RunnersZ"+UUID.randomUUID();var body=new MultipartBodyPublisher(b).add("file",file.getFileName().toString(),Files.readAllBytes(file),"application/octet-stream").add("password",password).build();var r=http.send(HttpRequest.newBuilder(URI.create(config.baseUrl()+path)).header("Authorization","Bearer "+config.token()).header("Content-Type","multipart/form-data; boundary="+b).POST(body).build(),HttpResponse.BodyHandlers.ofByteArray());if(r.statusCode()!=200)throw new IOException(new String(r.body()));return r.body();}
 static final class MultipartBodyPublisher{final String b;final List<byte[]> p=new ArrayList<>();MultipartBodyPublisher(String b){this.b=b;}MultipartBodyPublisher add(String n,String fn,byte[] d,String ct){p.add(("--"+b+"\r\nContent-Disposition: form-data; name=\""+n+"\"; filename=\""+fn+"\"\r\nContent-Type: "+ct+"\r\n\r\n").getBytes());p.add(d);p.add("\r\n".getBytes());return this;}MultipartBodyPublisher add(String n,String v){p.add(("--"+b+"\r\nContent-Disposition: form-data; name=\""+n+"\"\r\n\r\n"+v+"\r\n").getBytes());return this;}HttpRequest.BodyPublisher build(){p.add(("--"+b+"--\r\n").getBytes());return HttpRequest.BodyPublishers.ofByteArrays(p);}}
}